## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/sacroplastyLogic.ts`

```typescript
// Sacroplasty Clinical Decision Logic
// Based on:
// - Frey ME, et al. Sacroplasty: a ten-year analysis of prospective patients treated with percutaneous sacroplasty. Spine. 2017.
// - Pommersheim W, et al. Sacroplasty: a treatment for sacral insufficiency fractures. AJNR. 2003.
// - Denis F. The three column spine and its significance in the classification of acute thoracolumbar spinal injuries. Spine. 1983.
// - SIR/CIRSE Consensus Guidelines for Vertebral Augmentation (2014)
// - ACR Appropriateness Criteria: Sacral Insufficiency Fractures (2022)

export type DenisZone = "zone1" | "zone2" | "zone3" | "";

export type SacroplastyInput = {
  age: string;
  vasScore: string;             // Visual Analog Scale 0-10
  functionalImpairment: string; // mild | moderate | severe
  // Fracture characteristics
  denisZone: string;
  bilateral: boolean;
  mriEdema: boolean;            // bone marrow edema on MRI
  ctFractureLine: boolean;
  fractureAgeWeeks: string;
  hShapeFracture: boolean;      // H-shaped or "Honda sign" on bone scan/MRI
  // Etiology
  osteoporosis: boolean;
  malignancy: boolean;
  radiation: boolean;           // radiation-induced insufficiency fracture
  // Conservative therapy
  conservativeWeeks: string;
  analgesicsUsed: boolean;
  ptUsed: boolean;
  mobilityAids: boolean;
  // Contraindications
  activeInfection: boolean;
  coagulopathy: boolean;
  sacralNerveCompression: boolean;
  bowelBladderDysfunction: boolean;
  allergy: boolean;
  pregnancy: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return {
    I: "Class I — Recommended",
    IIa: "Class IIa — Reasonable",
    IIb: "Class IIb — May Be Considered",
    III: "Class III — Not Recommended / Contraindicated",
  }[cor];
}

export function getCORColor(cor: COR): string {
  return {
    I: "border-green-500 text-green-700",
    IIa: "border-blue-500 text-blue-700",
    IIb: "border-yellow-500 text-yellow-700",
    III: "border-red-500 text-red-700",
  }[cor];
}

export function assessSacroplasty(input: SacroplastyInput) {
  const contraindications: string[] = [];
  const rationale: string[] = [];
  const optimizationSteps: string[] = [];

  // Absolute contraindications
  if (input.activeInfection) contraindications.push("Active systemic or local infection — absolute contraindication to sacroplasty");
  if (input.coagulopathy) contraindications.push("Uncorrected coagulopathy — correct before proceeding (INR <1.5, platelets >50,000)");
  if (input.sacralNerveCompression) contraindications.push("Sacral nerve root compression with neurologic deficit — surgical decompression required before sacroplasty");
  if (input.bowelBladderDysfunction) contraindications.push("Bowel or bladder dysfunction — evaluate for sacral nerve involvement; neurosurgical consultation required");
  if (input.pregnancy) contraindications.push("Pregnancy — defer elective sacroplasty; radiation exposure risk");
  if (input.allergy) contraindications.push("Known allergy to bone cement (PMMA) or contrast — use alternative cement or premedicate");

  if (contraindications.length > 0) {
    return {
      recommendation: "Sacroplasty Contraindicated",
      cor: "III" as COR,
      loe: "C",
      urgency: "Contraindicated",
      rationale: ["Absolute contraindication(s) identified — address before proceeding."],
      contraindications,
      optimizationSteps: ["Resolve contraindication(s) before reassessing candidacy"],
      denisZoneNote: "",
    };
  }

  const vas = parseFloat(input.vasScore) || 0;
  const fractureWeeks = parseFloat(input.fractureAgeWeeks) || 0;
  const conservWeeks = parseFloat(input.conservativeWeeks) || 0;

  let cor: COR = "IIb";
  let urgency = "Elective";

  // Denis Zone classification
  // Zone 1: Sacral ala (lateral to foramina) — most common insufficiency fracture site
  // Zone 2: Sacral foramina — risk of nerve root injury
  // Zone 3: Central sacral canal — highest risk, rare

  const isZone1 = input.denisZone === "zone1";
  const isZone2 = input.denisZone === "zone2";
  const isZone3 = input.denisZone === "zone3";

  if (
    (input.mriEdema || input.ctFractureLine) &&
    (isZone1 || isZone2) &&
    vas >= 4 &&
    conservWeeks >= 2 &&
    (input.osteoporosis || input.malignancy || input.radiation)
  ) {
    cor = "I";
    urgency = input.malignancy ? "Pathologic Fracture — Expedited" : "Appropriate";
    rationale.push(`Sacral insufficiency fracture — Denis ${input.denisZone === "zone1" ? "Zone 1 (sacral ala)" : "Zone 2 (sacral foramina)"} with imaging-confirmed fracture`);
    rationale.push(`VAS pain score ${vas}/10 — severe pain supporting intervention`);
    if (input.hShapeFracture) rationale.push("H-shaped (Honda sign) bilateral sacral fracture — sacroplasty provides bilateral stabilization");
    if (input.bilateral) rationale.push("Bilateral sacral fractures — bilateral sacroplasty recommended for adequate stabilization");
    if (input.malignancy) rationale.push("Pathologic fracture from malignancy — sacroplasty provides rapid pain relief and structural support");
    if (input.radiation) rationale.push("Radiation-induced insufficiency fracture — sacroplasty is appropriate for refractory pain");
    rationale.push("Conservative therapy trial completed — sacroplasty is recommended per ACR Appropriateness Criteria");
  } else if (
    (input.mriEdema || input.ctFractureLine) &&
    vas >= 3 &&
    conservWeeks >= 2
  ) {
    cor = "IIa";
    urgency = "Reasonable";
    rationale.push("Sacral insufficiency fracture with imaging confirmation and persistent pain after conservative therapy");
    if (isZone3) {
      rationale.push("Denis Zone 3 (central canal) — higher risk of cement extravasation into spinal canal; proceed with extreme caution");
      optimizationSteps.push("Zone 3 fractures: Neurosurgical consultation recommended; consider alternative pain management");
    }
  } else if (conservWeeks < 2) {
    cor = "IIb";
    urgency = "Continue Conservative Therapy";
    rationale.push("Conservative therapy trial insufficient — most payers require ≥6 weeks for sacral insufficiency fractures");
    optimizationSteps.push("Continue analgesics, physical therapy, and mobility aids for ≥6 weeks");
    optimizationSteps.push("Document pain scores and functional status at each visit");
    optimizationSteps.push("Calcitonin nasal spray may accelerate fracture healing in osteoporotic insufficiency fractures");
  } else if (!input.mriEdema && !input.ctFractureLine) {
    cor = "IIb";
    urgency = "Imaging Confirmation Required";
    rationale.push("MRI bone marrow edema or CT fracture line not documented");
    optimizationSteps.push("Obtain MRI pelvis with STIR sequences to confirm sacral insufficiency fracture and bone marrow edema");
    optimizationSteps.push("Bone scan or SPECT-CT can confirm fracture activity if MRI is contraindicated");
  } else {
    cor = "IIb";
    urgency = "Insufficient Criteria";
    optimizationSteps.push("Document VAS ≥4 and functional impairment (inability to ambulate, transfer, or perform ADLs)");
    optimizationSteps.push("Confirm Denis zone classification on imaging");
    optimizationSteps.push("Complete ≥6-week conservative therapy trial with documentation");
  }

  // Denis zone note
  let denisZoneNote = "";
  if (isZone1) {
    denisZoneNote = "Denis Zone 1 (sacral ala, lateral to foramina): Most common site for insufficiency fractures. Lowest risk for sacroplasty — cement extravasation away from neural structures. Standard sacroplasty approach.";
  } else if (isZone2) {
    denisZoneNote = "Denis Zone 2 (sacral foramina): Moderate risk — cement extravasation can injure sacral nerve roots (S1-S4). Use low-viscosity cement with fluoroscopic/CT guidance. Consider CT-guided approach for precise needle placement.";
  } else if (isZone3) {
    denisZoneNote = "Denis Zone 3 (central sacral canal): Highest risk — cement extravasation can cause cauda equina syndrome. Sacroplasty is relatively contraindicated; neurosurgical consultation strongly recommended.";
  } else {
    denisZoneNote = "Denis zone classification required for procedural planning and risk assessment. Obtain CT or MRI to classify fracture location relative to sacral foramina.";
  }

  return {
    recommendation:
      cor === "I"
        ? "Sacroplasty Recommended"
        : cor === "IIa"
        ? "Sacroplasty Reasonable"
        : urgency === "Continue Conservative Therapy"
        ? "Continue Conservative Therapy — Sacroplasty Premature"
        : urgency === "Imaging Confirmation Required"
        ? "MRI/CT Imaging Required Before Proceeding"
        : "Insufficient Criteria for Sacroplasty",
    cor,
    loe: input.mriEdema ? "B" : "C",
    urgency,
    rationale,
    contraindications,
    optimizationSteps,
    denisZoneNote,
  };
}
